import re

def clean_text(text):
    no_symbols = re.sub(r'[^\w\s]', '', text)
    return re.sub(r'\s+', ' ', no_symbols).strip()

import re

def most_frequent_words(text, n):
    counts = {}
    for w in re.findall(r'\w+', text):
        counts[w] = counts.get(w, 0) + 1
    pairs = [(c, w) for w, c in counts.items()]
    return sorted(pairs, reverse=True)[:n]
